"""
Flask 应用工厂
框架代码，不包含具体业务逻辑
"""
import os
from flask import Flask, render_template
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS
from app_config import get_config

db = SQLAlchemy()

# 项目根目录
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def create_app(config_name=None):
    """应用工厂函数"""
    # 设置模板路径
    template_dir = os.path.join(BASE_DIR, 'templates')
    app = Flask(__name__, template_folder=template_dir)

    # 加载配置
    if config_name:
        app.config.from_object(config_name)
    else:
        app.config.from_object(get_config())

    # 初始化扩展
    db.init_app(app)

    # CORS 支持
    CORS(app)

    # ==== 在这里注册业务蓝图 ====
    from app.routes.comment_routes import comments_bp
    app.register_blueprint(comments_bp, url_prefix='/api/comments')
    from app.routes.blog_routes import blogs_bp
    app.register_blueprint(blogs_bp, url_prefix='/api/blogs')
    from app.routes.image_upload_routes import image_upload_bp
    app.register_blueprint(image_upload_bp, url_prefix='/api/upload')
    # ==============================

    # 首页路由
    @app.route('/')
    def index():
        return render_template('index.html')

    @app.route('/blogs')
    def blog_list():
        return render_template('blog_list.html')

    @app.route('/blog/<int:blog_id>')
    def blog_detail(blog_id):
        return render_template('blog_detail.html')

    @app.route('/blog/new')
    def blog_new():
        return render_template('blog_new.html')

    # 健康检查
    @app.route('/health')
    def health():
        return {'status': 'ok'}

    # 创建数据库表
    with app.app_context():
        db.create_all()

    return app

from flask import Blueprint, request, jsonify
from app.models.blog import Blog
from app import db

blogs_bp = Blueprint('blogs', __name__)

@blogs_bp.route('/', methods=['GET'])
def get_blogs():
    blogs = Blog.query.all()
    return jsonify([blog.to_dict() for blog in blogs])

@blogs_bp.route('/', methods=['POST'])
def create_blog():
    data = request.get_json()
    new_blog = Blog(
        title=data['title'],
        description=data['description'],
        image_url=data.get('image_url')
    )
    db.session.add(new_blog)
    db.session.commit()
    return jsonify(new_blog.to_dict()), 201

@blogs_bp.route('/<int:blog_id>', methods=['GET'])
def get_blog(blog_id):
    blog = Blog.query.get_or_404(blog_id)
    return jsonify(blog.to_dict())

@blogs_bp.route('/<int:blog_id>', methods=['PUT'])
def update_blog(blog_id):
    blog = Blog.query.get_or_404(blog_id)
    data = request.get_json()
    blog.title = data['title']
    blog.description = data['description']
    blog.image_url = data.get('image_url')
    db.session.commit()
    return jsonify(blog.to_dict())

@blogs_bp.route('/<int:blog_id>', methods=['DELETE'])
def delete_blog(blog_id):
    blog = Blog.query.get_or_404(blog_id)
    db.session.delete(blog)
    db.session.commit()
    return jsonify({'message': 'Blog deleted successfully'})

from flask import Blueprint, request, jsonify
import os
from werkzeug.utils import secure_filename

image_upload_bp = Blueprint('image_upload', __name__)

UPLOAD_FOLDER = 'app/static/uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@image_upload_bp.route('/api/upload', methods=['POST'])
def upload_image():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part in the request'}), 400

    file = request.files['file']

    if file.filename == '':
        return jsonify({'error': 'No file selected for uploading'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        file_path = os.path.join(UPLOAD_FOLDER, filename)
        file.save(file_path)
        file_url = f'/static/uploads/{filename}'
        return jsonify({'message': 'File successfully uploaded', 'url': file_url}), 201
    else:
        return jsonify({'error': 'Allowed file types are png, jpg, jpeg, gif'}), 400
